'use strict';
const previewCache=new Map();
async function previewJSON(path){if(!previewCache.has(path))previewCache.set(path,fetch(path).then(r=>{if(!r.ok)throw Error('Preview unavailable');return r.json()}));return previewCache.get(path)}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function receipt(rows){return '<dl class="preview-receipt">'+rows.map(([a,b])=>`<div><dt>${esc(a)}</dt><dd>${esc(b)}</dd></div>`).join('')+'</dl>'}
async function mountMesh(canvas,phase='after'){const mesh=await previewJSON('/data/cad/'+phase+'.mesh.json');if(!canvas.isConnected)return;const ctx=canvas.getContext('2d');let yaw=-.55,pitch=.9,drag=null;function draw(){if(!canvas.isConnected)return;const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,r.width,r.height);const scale=Math.min(r.width/150,r.height/140),c=Math.cos(yaw),s=Math.sin(yaw),sp=Math.sin(pitch),cp=Math.cos(pitch);const v=mesh.vertices.map(([x,y,z])=>{const xx=x*c-y*s,yy=x*s+y*c;return[r.width/2+xx*scale,r.height/2+(yy*sp-z*cp)*scale,yy*cp+z*sp]});const faces=mesh.triangles.map(t=>{const a=mesh.vertices[t[0]],b=mesh.vertices[t[1]],e=mesh.vertices[t[2]],u=b.map((x,i)=>x-a[i]),w=e.map((x,i)=>x-a[i]),n=[u[1]*w[2]-u[2]*w[1],u[2]*w[0]-u[0]*w[2],u[0]*w[1]-u[1]*w[0]],shade=Math.round(142+Math.abs((n[0]*-.3+n[1]*-.4+n[2]*.86)/(Math.hypot(...n)||1))*69);return{t,shade,z:t.reduce((sum,i)=>sum+v[i][2],0)/3}}).sort((a,b)=>a.z-b.z);for(const f of faces){ctx.beginPath();f.t.forEach((i,j)=>j?ctx.lineTo(v[i][0],v[i][1]):ctx.moveTo(v[i][0],v[i][1]));ctx.closePath();ctx.fillStyle=`rgb(${f.shade-3},${f.shade+4},${f.shade-7})`;ctx.fill();ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=.35;ctx.stroke()}ctx.fillStyle='#5f6b7a';ctx.font='10px monospace';ctx.fillText('ACTUAL CAD EXPORT / '+phase.toUpperCase(),16,24)}canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.009;pitch=Math.max(.3,Math.min(1.35,pitch+(e.clientY-drag[1])*.007));drag=[e.clientX,e.clientY];draw()};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;canvas.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key))return;e.preventDefault();if(e.key==='Home'){yaw=-.55;pitch=.9}else if(e.key==='ArrowLeft')yaw-=.12;else if(e.key==='ArrowRight')yaw+=.12;else pitch=Math.max(.3,Math.min(1.35,pitch+(e.key==='ArrowUp'?-.08:.08)));draw()};const ro=new ResizeObserver(()=>{if(canvas.isConnected)draw();else ro.disconnect()});ro.observe(canvas);draw()}
let previewRequest=0;
async function renderPackagePreview(family,index){const root=document.querySelector('#package-preview');if(!root)return;const request=++previewRequest;root.innerHTML='<p class="small">Loading the actual sample…</p>';const show=html=>{if(request!==previewRequest)return false;root.innerHTML=html;return true};const model=()=>'<canvas class="package-mesh" tabindex="0" role="img" aria-label="Actual exported CAD solid. Drag or use arrow keys to rotate."></canvas>';
try{
if(family==='robot'){
if(index===0)show('<video controls playsinline muted preload="metadata" poster="/data/robot/poster.jpg" aria-label="Preview robot camera recording"><source src="/data/robot/episode_000000.mp4" type="video/mp4"></video><p class="preview-caption">BridgeData V2 / episode 0 · 28 frames · 5 Hz · 5.6 seconds</p>');
if(index===1){const d=await previewJSON('/data/robot/episode.json');if(show('<label class="small" for="preview-frame">Inspect a recorded step <output id="preview-frame-number">0</output></label><input id="preview-frame" aria-label="Package record frame" type="range" min="0" max="27" value="0"><div id="preview-record"></div><p class="preview-caption">Source values rounded to six decimals for display; full precision remains in the original records. Units and action convention are unspecified in this conversion.</p>')){const draw=()=>{const n=Number(root.querySelector('input').value),f=d.frames[n];root.querySelector('output').textContent=n+' / 27 · '+Number(f.timestamp).toFixed(1)+' s';root.querySelector('#preview-record').innerHTML='<div class="signal-head"><span>Field</span><span>State</span><span>Action</span></div>'+d.fields['observation.state'].names.map((name,j)=>{const series=d.frames.map(v=>v['observation.state'][j]),min=Math.min(...series),range=Math.max(...series)-min||1;return `<div class="signal-row"><span>${esc(name)}<svg viewBox="0 0 100 20" aria-hidden="true"><polyline points="${series.map((v,k)=>`${k/27*100},${18-(v-min)/range*16}`).join(' ')}" fill="none" stroke="#c97b08" stroke-width="1.5"/><line x1="${n/27*100}" x2="${n/27*100}" y1="0" y2="20" stroke="#171717"/></svg></span><span>${f['observation.state'][j].toFixed(6)}</span><span>${f.action[j].toFixed(6)}</span></div>`}).join('')};root.querySelector('input').oninput=draw;draw()}}
if(index===2){const d=await previewJSON('/data/robot/episode.json');show('<div class="instruction-preview"><img src="/data/robot/poster.jpg" alt="Camera frame paired with the spoon-transfer instruction"><div><span class="kicker">DATASET-AUTHORED INSTRUCTION</span><blockquote>“'+esc(d.instruction)+'”</blockquote><p class="small">Task 0 → episode 0 → frames 0–27</p></div></div>')}
if(index===3){const d=await previewJSON('/data/robot/manifest.json');show(receipt([['Source','BridgeData V2 → jesbu1 LeRobot conversion'],['Pinned revision',d.source_revision],['Video / records',d.validation.video_frames+' frames / '+d.validation.parquet_rows+' rows'],['Timing',d.validation.fps+' Hz · contiguous frame indices'],['Rights','Original: CC BY 4.0 · conversion: Apache-2.0'],['Preparation','H.264 browser transcode; numerical records preserved']])+'<details><summary>Inspect one retained file hash</summary><p class="hash">'+esc(d.files.find(f=>f.path==='episode_000000.parquet').sha256)+'</p></details>')}
}
if(family==='inspection'){
if(index===0)show('<img class="package-pcb" src="/data/inspection/pcb1_0_image.jpg" alt="Original VisA circuit-board inspection image"><p class="preview-caption">Actual test image · 1404 × 1070 pixels · VisA pcb1 / 000</p>');
if(index===1){if(show('<div class="mask-pair"><figure><canvas id="package-mask-image" width="620" height="480"></canvas><figcaption>Source detail</figcaption></figure><figure><canvas id="package-mask-label" width="620" height="480"></canvas><figcaption>Reference mask: white = anomaly</figcaption></figure></div><p class="preview-caption">Matching crop from the original image and supplied binary label. Region around connector pins, not an inferred prediction.</p>')){for(const [id,file]of [['package-mask-image','pcb1_0_image.jpg'],['package-mask-label','pcb1_0_mask.png']]){const canvas=root.querySelector('#'+id),img=new Image();img.onload=()=>{const c=canvas.getContext('2d');c.imageSmoothingEnabled=id!=='package-mask-label';c.drawImage(img,480,690,310,240,0,0,620,480)};img.src='/data/inspection/'+file}}}
if(index===2){const d=await previewJSON('/data/inspection/inspection-specimen.json');show('<div class="sample-id"><img src="/data/inspection/pcb1_0_image.jpg" alt="Documented circuit board"><span>'+esc(d.specimen_id)+'</span></div>'+receipt([['Purpose','Locate anomalous pixels'],['Split','Held-out test example'],['Image and mask',d.input.width+' × '+d.input.height+' · pixel aligned'],['Label encoding','0 = background · 255 = annotated anomaly'],['Usage rights',d.license],['Source','VisA, ECCV 2022 · pinned BrachioLab mirror']]))}
if(index===3){const d=await previewJSON('/data/inspection/annotation-measurements.json');show('<div class="measurement-preview"><strong>'+d.positive_pixels.toLocaleString('en-US')+'<span>annotated pixels</span></strong><strong>'+d.image_coverage_percent.toFixed(3)+'%<span>of the full image</span></strong></div><div class="bounds-picture"><img src="/data/inspection/pcb1_0_image.jpg" alt="Annotation position on full board"><span></span></div>'+receipt([['Region bounds','x 537–574 · y 755–856 (inclusive)'],['Image extent','1404 × 1070 pixels'],['Interpretation','Annotation geometry, not model confidence']]))}
}
if(family==='cad'){
if(index===0){const response=await fetch('/data/cad/before.py'),source=await response.text();if(show('<div class="source-model">'+model()+'<pre class="source-preview"></pre></div><p class="preview-caption">Actual starting solid + excerpt of its editable CadQuery source. Download retains the full program.</p>')){root.querySelector('pre').textContent=source.split('\n').filter(l=>!l.startsWith('#')).slice(0,25).join('\n');mountMesh(root.querySelector('canvas'),'before')}}
if(index===1){if(show(model()+'<div class="preview-tags"><span>Ø30 mm bore</span><span>80 × 100 × 10 mm</span><span>1 valid solid</span></div><p class="preview-caption">Interactive tessellated preview of the exported reference solid. STEP download preserves the exchange geometry. Drag or arrow keys to orbit.</p>'))mountMesh(root.querySelector('canvas'),'after')}
if(index===2){const d=await previewJSON('/data/cad/validation.json');show('<p class="instruction-line">'+esc(d.edit.instruction)+'</p><div class="diameter-change"><span>Ø22<small>before / mm</small></span><b>→</b><span>Ø30<small>after / mm</small></span></div>'+receipt([['Solid validity',String(d.before.valid)+' → '+String(d.after.valid)],['Outer dimensions','80 × 100 × 10 mm → unchanged'],['Volume',d.before.volume_mm3.toFixed(2)+' → '+d.after.volume_mm3.toFixed(2)+' mm³'],['Material removed',d.edit.actual_volume_removed_mm3.toFixed(2)+' mm³'],['STEP readback','Both exported files reimport as valid single solids']])+'<p class="preview-caption">Checks recorded during CAD generation; not a load or manufacturing assessment.</p>')}
if(index===3){const response=await fetch('/data/cad/ATTRIBUTION.txt'),attribution=await response.text();show('<div class="license-badge"><span>REUSE RECORD</span><strong>Apache 2.0</strong><p>CadQuery official pillow-block example</p></div>'+receipt([['Source owner','Contributors to CadQuery'],['Original program','Ex003_Pillow_Block_With_Counterbored_Holes.py'],['Pinned revision','33361dc1b5b70bc83ce36f1b34a01ca85dfca80a'],['Authored change','Centre bore 22 → 30 mm; exported STEP / mesh'],['Attribution','Source and modification notice retained']])+'<details><summary>Read the full attribution</summary><p class="small">'+esc(attribution)+'</p></details>')}
}
}catch{show('<p>Preview unavailable. Download the original file below or reload the page.</p>')}
}
if(document.querySelector('#home-cad-preview'))mountMesh(document.querySelector('#home-cad-preview'),'after');
// Compact offering-card visuals use the same retained specimen bytes.
if(document.querySelector('#card-cad-preview'))mountMesh(document.querySelector('#card-cad-preview'),'after');
if(document.querySelector('#card-pcb-preview')){const c=document.querySelector('#card-pcb-preview'),im=new Image();im.onload=()=>c.getContext('2d').drawImage(im,480,690,310,240,0,0,620,480);im.src='/data/inspection/pcb1_0_image.jpg'}
